function UICultivateEquipLevelAttributeNode:RefreshUI(attributeId, attributeNum, additionNum, unlockAttrLevel, isCanActive, isMainAttr)
    local isOwnAttribute = checkNumber(attributeId) > 0
    KTool.SetActive(self.AttributeNode.gameObject, isOwnAttribute)
    KTool.SetActive(self.UnlockNode.gameObject, not isOwnAttribute)

    if isOwnAttribute then
        self:RefreshAttributeNode(attributeId, attributeNum, additionNum, isMainAttr)
    else
        self:RefreshUnlockNode(unlockAttrLevel, isCanActive)
    end
end

function UICultivateEquipLevelAttributeNode:RefreshAttributeNode(attrAdditionId, attributeNum, additionNum, isMainAttr)
    local isShowAdditionNum = checkNumber(additionNum) > 0
    KTool.SetActive(self.ArrowNode.gameObject, isShowAdditionNum)
    KTool.SetActive(self.AdditionAttributeNumText.gameObject, isShowAdditionNum)
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId)

    self.AttributeNameText.text = attrAdditionVo.attrAdditionName
    -- self.AttributeNameText.Status = isMainAttr and 1 or 2
    self.CurrentAttributeNumText.text = attribute_format(attrAdditionVo.isConversion, attributeNum)
    -- self.CurrentAttributeNumText.Status = isMainAttr and 1 or 2
    if isShowAdditionNum then
        self.AdditionAttributeNumText.text = attribute_format(attrAdditionVo.isConversion, attributeNum + additionNum)
    end

    local attrConf = cardConfMgr:GetBasicAttr(attrAdditionVo.attrId)
    self.AttrIcon:LoadSprite(attrConf.icon)
end

function UICultivateEquipLevelAttributeNode:RefreshUnlockNode(unlockAttrLevel, isCanActive)
    self.AttributeUnlockTipText.text = localize("Lv_num_", {_num_ = unlockAttrLevel})
end

---RefreshActivationText
---@param isActivation boolean 是否激活
function UICultivateEquipLevelAttributeNode:RefreshActivationText(isActivation)
    KTool.SetActive(self.ActivationText.gameObject, isActivation)
end

function UICultivateEquipLevelAttributeNode:RefreshAttrBgStatus(status)
    self.AttrBg.Status = status
end

